      "arFull": "الٓرٰ ۫ تِلْكَ اٰیٰتُ الْكِتٰبِ الْحَكِیْمِ ۟",
      "ur": "الرٰ۔ یہ پرحکمت کتاب کی آیتیں ہیں۔[1]",
      "en": "Alif, Lām, Rā.[510] These are the verses of the wise[511] Book.",
      "footnotesUr": "[1] اَلْحَکِیْمِ، کتاب یعنی قرآن مجید کی صفت ہے۔ اس کے ایک تو وہی معنی ہیں جو ترجمے میں اختیار کئے گئے ہیں۔ اس کے اور بھی کئی معنی کئے گئے ہیں مثلاً اَلْمُحْکَمْ، یعنی حلال و حرام اور حدود و احکام میں محکم (مضبوط) ہے۔ حکیم بمعنی حاکم۔ یعنی اختلافات میں لوگوں کے درمیان فیصلہ کرنے والی کتاب۔ (البقرۃ: 23)، یعنی اللہ تعالٰی نے اس میں عدل و انصاف کے ساتھ فیصلے کئے ہیں۔",
