      "number": 6,
      "arFull": "اِنَّ فِی اخْتِلَافِ الَّیْلِ وَالنَّهَارِ وَمَا خَلَقَ اللّٰهُ فِی السَّمٰوٰتِ وَالْاَرْضِ لَاٰیٰتٍ لِّقَوْمٍ یَّتَّقُوْنَ ۟",
