      "arFull": "وَلَقَدْ اَهْلَكْنَا الْقُرُوْنَ مِنْ قَبْلِكُمْ لَمَّا ظَلَمُوْا ۙ وَجَآءَتْهُمْ رُسُلُهُمْ بِالْبَیِّنٰتِ وَمَا كَانُوْا لِیُؤْمِنُوْا ؕ كَذٰلِكَ نَجْزِی الْقَوْمَ الْمُجْرِمِیْنَ ۟",
      "ur": "اور ہم نے تم سے پہلے بہت سے گروہوں کو ہلاک کردیا جب کہ انہوں نے ﻇلم کیا حاﻻنکہ ان کے پاس ان کے پیغمبر بھی دﻻئل لے کر آئے، اور وه ایسے کب تھے کہ ایمان لے آتے؟ ہم مجرم لوگوں کو ایسی ہی سزا دیا کرتے ہیں۔[1]",
      "en": "And We had already destroyed generations before you when they wronged, and their messengers had come to them with clear proofs, but they were not to believe. Thus do We recompense the criminal people.",
      "footnotesUr": "[1] یہ کفار کو تنبیہ ہے کہ گزشتہ امتوں کی طرح تم بھی ہلاکت سے دو چار ہو سکتے ہو۔",
