      "number": 31,
      "arFull": "قُلْ مَنْ یَّرْزُقُكُمْ مِّنَ السَّمَآءِ وَالْاَرْضِ اَمَّنْ یَّمْلِكُ السَّمْعَ وَالْاَبْصَارَ وَمَنْ یُّخْرِجُ الْحَیَّ مِنَ الْمَیِّتِ وَیُخْرِجُ الْمَیِّتَ مِنَ الْحَیِّ وَمَنْ یُّدَبِّرُ الْاَمْرَ ؕ فَسَیَقُوْلُوْنَ اللّٰهُ ۚ فَقُلْ اَفَلَا تَتَّقُوْنَ ۟",
      "ur": "آپ کہیے کہ وه کون ہے جو تم کو آسمان اور زمین سے رزق پہنچاتا ہے یا وه کون ہے جو کانوں اور آنکھوں پر پورا اختیار رکھتا ہے اور وه کون ہے جو زنده کو مرده سے نکالتا ہے اور مرده کو زنده سے نکالتا ہے اور وه کون ہے جو تمام کاموں کی تدبیر کرتا ہے؟ ضرور وه یہی کہیں گے کہ اللہ [1] تو ان سے کہیے کہ پھر کیوں نہیں ڈرتے.",
      "en": "Say, \"Who provides for you from the heaven and the earth? Or who controls hearing and sight and who brings the living out of the dead and brings the dead out of the living and who arranges [every] matter?\" They will say, \"Allāh,\" so say, \"Then will you not fear Him?\"",
      "footnotesUr": "[1] اس آیت سے بھی واضح ہے کہ مشرکین اللہ تعالٰی کی مالکیت، خالقیت، ربویت اور اس کے مدبر الامور ہونے کو تسلیم کرتے تھے۔ لیکن اس کے باوجود چونکہ وہ اس کی الوہیت میں دوسروں کو شریک ٹھہراتے تھے، اس لئے اللہ تعالٰی انہیں جہنم کا ایندھن قرار دیا۔ آج کل کے مدعیان ایمان بھی اسی توحید الوہیت کے منکر ہیں۔ فَتَشَابَهَتْ قُلُوبُهُمْ (هَدَاهُمُ اللهُ تَعَالَى)",
      "footnotesEn": null,
