      "arFull": "ثُمَّ قِیْلَ لِلَّذِیْنَ ظَلَمُوْا ذُوْقُوْا عَذَابَ الْخُلْدِ ۚ هَلْ تُجْزَوْنَ اِلَّا بِمَا كُنْتُمْ تَكْسِبُوْنَ ۟",
