      "arFull": "وَلَا یَحْزُنْكَ قَوْلُهُمْ ۘ اِنَّ الْعِزَّةَ لِلّٰهِ جَمِیْعًا ؕ هُوَ السَّمِیْعُ الْعَلِیْمُ ۟",
