      "arFull": "هُوَ الَّذِیْ جَعَلَ لَكُمُ الَّیْلَ لِتَسْكُنُوْا فِیْهِ وَالنَّهَارَ مُبْصِرًا ؕ اِنَّ فِیْ ذٰلِكَ لَاٰیٰتٍ لِّقَوْمٍ یَّسْمَعُوْنَ ۟",
