      "arFull": "مَتَاعٌ فِی الدُّنْیَا ثُمَّ اِلَیْنَا مَرْجِعُهُمْ ثُمَّ نُذِیْقُهُمُ الْعَذَابَ الشَّدِیْدَ بِمَا كَانُوْا یَكْفُرُوْنَ ۟۠",
