      "arFull": "وَقَالَ مُوْسٰی یٰقَوْمِ اِنْ كُنْتُمْ اٰمَنْتُمْ بِاللّٰهِ فَعَلَیْهِ تَوَكَّلُوْۤا اِنْ كُنْتُمْ مُّسْلِمِیْنَ ۟",
      "ur": "اور موسیٰ (علیہ السلام) نے فرمایا کہ اے میری قوم! اگر تم اللہ پر ایمان رکھتے ہو تو اسی پر توکل کرو اگر تم مسلمان ہو.[1]",
      "en": "And Moses said, \"O my people, if you have believed in Allāh, then rely upon Him, if you should be Muslims [i.e., submitting to Him].\"",
      "footnotesUr": "[1] بنی اسرائیل، فرعون کی طرف سے جس ذلت اور رسوائی کا شکار تھے، حضرت موسیٰ (عليه السلام) کے آنے کے بعد بھی اس میں کمی نہیں آئی، اس لئے وہ سخت پریشان تھے، بلکہ حضرت موسیٰ (عليه السلام) سے انہوں نے یہ تک کہہ دیا، اے موسٰی، جس طرح تیرے آنے سے پہلے ہم فرعون اور اس کی قوم کی طرف سے تکلیفوں میں مبتلا تھے، تیرے آنے کے بعد بھی ہمارا یہی حال ہے۔ جس پر حضرت موسیٰ (عليه السلام) نے انہیں کہا تھا کہ امید ہے کہ میرا رب جلدی تمہارے دشمن کو ہلاک کر دے گا۔ لیکن اس کے لئے ضروری ہے کہ تم صرف ایک اللہ سے مدد چاہو اور صبر کا دامن ہاتھ سے نہ چھوڑو (ملاحظہ ہو سورۃ الاعراف آیات 128-129) یہاں بھی حضرت موسیٰ (عليه السلام) نے انہیں تلقین کی کہ اگر تم اللہ کے سچے فرمانبردار ہو تو اسی پر توکل کرو۔",
      "footnotesEn": null,
